<?php
namespace App\Models;
use App\Domain\Foundation\Traits\BelongsToCollege; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class AcademicAttendance extends Model { use BelongsToCollege; protected $table='academic_attendances'; protected $guarded=['id']; protected function casts():array{return ['attendance_date'=>'date'];} public function student():BelongsTo{return $this->belongsTo(Student::class);} public function studentEnrollment():BelongsTo{return $this->belongsTo(StudentEnrollment::class);} public function academicYear():BelongsTo{return $this->belongsTo(AcademicYear::class);} public function academicTerm():BelongsTo{return $this->belongsTo(AcademicTerm::class);} public function subjectEnrollment():BelongsTo{return $this->belongsTo(AcademicSubjectEnrollment::class,'student_subject_enrollment_id');} public function subject():BelongsTo{return $this->belongsTo(Subject::class);} public function section():BelongsTo{return $this->belongsTo(Section::class);} public function faculty():BelongsTo{return $this->belongsTo(Faculty::class);} }
